"""vpsilin.py (v-fp-build): independent linearised psi screen. Designs generated by fp-build's design.py (their
search, unchanged); then I rebuild every state with SYMBOLIC injection scalars in my own arithmetic (vfg.py), form
one column per (state, monomial), and decide exactly over Q whether e_(l, L1) is in the column span (my own
elimination). Compared bit by bit with fp-build's psi_lin_screen on the same design."""
import sys, random, time, collections
from fractions import Fraction as Fr
import os as _os; _HERE = _os.path.dirname(_os.path.abspath(__file__)); sys.path.insert(0, _os.path.join(_HERE, "..", "..", "frame-game"))
import fpa, design as D
from vfg import FG
m, trials, depth, seed = map(int, sys.argv[1:5]); dup = "dup" in sys.argv[5:]
S = fpa.Sp(m); V = FG(m); rng = random.Random(seed)
def padd(a, b, co=None):  # polynomial dict add: a + co*b, co a monomial dict
    out = dict(a)
    for kb, vb in b.items():
        if co is None:
            out[kb] = out.get(kb, 0) + vb
        else:
            for kc, vc in co.items():
                k = tuple(sorted(kb + kc)); out[k] = out.get(k, 0) + vb * vc
    return {k: v for k, v in out.items() if v != 0}
def build_sym(P):
    p2 = V.from_rows(P.p2)
    inj = [(rg, sl, src, V.from_rows(mu)) for (rg, sl, src, mu, co) in P.inj]
    one = {(): Fr(1)}
    states = [{(0, V.I): one}, {(1, V.I): one}]; out = {}
    def lm(g, c): return {(l, V.mul(g, h)): v for (l, h), v in c.items()}
    def add(c1, c2, co=None):
        o = dict(c1)
        for k, v in c2.items():
            o[k] = padd(o.get(k, {}), v, co)
            if not o[k]: del o[k]
        return o
    for reg in P.order:
        if reg == "R1": cur = dict(states[0])
        elif reg == "R2": cur = dict(states[1])
        elif reg == "Rt":
            c1 = states[out[("R1", P.a1 - 1)]] if P.a1 else states[0]
            c2 = states[out[("R2", P.a2 - 1)]] if P.a2 else states[1]
            cur = add(c1, lm(p2, c2))
        else:
            cur = dict(states[out[("Rt", P.tlen - 1)]])
        for k, u in enumerate(P.regs[reg]):
            for i, (rg, sl, src, mu) in enumerate(inj):
                if rg == reg and sl == k:
                    cur = add(cur, lm(mu, states[src]), {(i,): Fr(1)})
            cur = lm(V.tv(u), cur)
            states.append(cur); out[(reg, k)] = len(states) - 1
    return states
def in_span(cols, target):
    # cols: list of dict row->Fr ; exact elimination; is target in span?
    piv = {}  # pivot row -> reduced vector
    def reduce(v):
        v = dict(v)
        while True:
            ks = [k for k in v if k in piv]
            if not ks: return v
            k = ks[0]; f = v[k]; pv = piv[k]
            for kk, vv in pv.items():
                v[kk] = v.get(kk, 0) - f * vv
                if v[kk] == 0: del v[kk]
    for c in cols:
        r = reduce(c)
        if r:
            k = min(r, key=str); f = r[k]
            r = {kk: vv / f for kk, vv in r.items()}
            for pk in list(piv):
                if k in piv[pk]:
                    g = piv[pk][k]
                    piv[pk] = {kk: piv[pk].get(kk, 0) - g * r.get(kk, 0) for kk in set(piv[pk]) | set(r)}
                    piv[pk] = {kk: vv for kk, vv in piv[pk].items() if vv != 0}
            piv[k] = r
    return not reduce(target)
def my_psilin(states, l):
    cols = []
    for st in states:
        bym = {}
        for (ll, g), poly in st.items():
            key = (ll, V.pos(g))
            for mono, co in poly.items():
                d = bym.setdefault(mono, {}); d[key] = d.get(key, 0) + co
        for d in bym.values():
            d = {k: v for k, v in d.items() if v != 0}
            if d: cols.append(d)
    return in_span(cols, {(l, V.pos(V.K)): Fr(1)})
agree = collections.Counter(); t0 = time.time()
for tr in range(trials):
    P = D.Prog(S, m, rng, dup=(rng.randrange(m) if dup else 0))
    if not P.ok: continue
    for step in range(depth + 1):
        res = P.evaluate(); orph = P.orphan_list(res)
        if step == depth or not orph or [r[0] for r in res] == ["yes", "yes"]: break
        if P.try_repair(rng.choice(orph)) is None: break
    num = list(P.inj)
    P.inj = [(rg, sl, src, mu, fpa.Poly.var(i)) for i, (rg, sl, src, mu, co) in enumerate(num)]
    P.run()
    theirs = tuple(bool(fpa.psi_lin_screen(S, P.states, l)) for l in (0, 1))
    P.inj = num
    mine = tuple(my_psilin(build_sym(P), l) for l in (0, 1))
    agree["agree" if mine == theirs else f"DISAGREE mine={mine} theirs={theirs}"] += 1
    agree[f"mine {''.join(str(int(x)) for x in mine)}"] += 1
print(f"m={m} seed={seed} dup={dup}: {sum(v for k, v in agree.items() if k.startswith('mine'))} designs, {time.time()-t0:.0f}s")
for k, v in sorted(agree.items()): print("  ", k, v)
